 959	\begin{theorem}[Resampling a line parameter]
 960		\label{thm:line-parameter-resampling}
 961		\lean{MIPStarRE.QPBT.avgOver_lineRepMap_resample_parameter}
 962		\leanok
 963		\uses{def:line-representative}
 964		This auxiliary identity isolates the conditional sampling used in the
 965		proof of Lemma~\ref{lem:qld-xz-lines}; it is not a named statement of
 966		\cite{Ji2020MIPStar}. Let $K$ be a finite field, $m \geq 0$, and
 967		$v \in K^m$, and write $R_v = L^{\mathrm{Ln}}_v$ for the canonical line
 968		representative map of Definition~\ref{def:line-representative}.
 969		For every $f : K^m \times K^m \to \mathbb{R}$,
 970		\[
 971			\mathbb{E}_{u \in K^m} f(R_v(u),u)
 972			= \mathbb{E}_{u \in K^m}\mathbb{E}_{t \in K}
 973			f(R_v(u),R_v(u)+tv),
 974		\]
 975		where all averages are uniform. The identity includes $v=0$.
 976	\end{theorem}
 977	\begin{proof}
 978		\leanok
 979		\uses{def:line-representative}
 980		The point $R_v(u)+tv$ is uniform on $K^m$: each point has exactly
 981		$|K|$ preimages under $(u,t) \mapsto R_v(u)+tv$. Moreover,
 982		$R_v(R_v(u)+tv)=R_v(u)$. Applying these two identities to $f$ gives
 983		the result. When $v=0$, $R_v$ is the identity and $t$ is free.
 984	\end{proof}
